-- mission-control-db-contract: MP-01 multi-provider lane profiles (multi-provider SPEC-01,
-- ADR-0035 proposed delta; extends 0027 and 0030).
--
-- The Lane Profile vocabulary grows from three to seven: `claude_agent_sdk`, `codex`
-- (worker-hosted) and the provider-hosted `claude_cloud`, `codex_cloud`. Every profile row
-- carries a describe document; the four new rows are `mc.lane_describe.v2` **stubs** whose
-- every control and feature is `unqualified` (design intent, not proof). Nothing flips them
-- to qualified except a recorded qualification in a later release. `execution_binding`
-- admits the typed `mc.execution_binding.v2` document for the `claude` and `codex` lanes
-- beside the existing `mc.cursor_binding.v1` for `cursor`. Additive only: no existing row
-- or column changes; every widened CHECK still admits every row it admitted before.

-- ---------------------------------------------------------------------------------------
-- lane_profile: admit the two new lanes and the v2 describe shape.
ALTER TABLE mission_control.lane_profile
    DROP CONSTRAINT lane_profile_lane_check,
    ADD CONSTRAINT lane_profile_lane_check
        CHECK (lane IN ('deep_agents', 'cursor', 'claude', 'codex')),
    DROP CONSTRAINT lane_profile_check,
    ADD CONSTRAINT lane_profile_check CHECK ((
        describe->>'schema_version' IN ('mc.lane_describe.v1', 'mc.lane_describe.v2')
        AND describe->>'lane_profile' = lane_profile
        AND describe->>'lane' = lane
        AND describe->>'placement' = placement
        AND describe->'qualified' = to_jsonb(qualified)
        AND (describe->>'schema_version' = 'mc.lane_describe.v1'
             OR (jsonb_typeof(describe->'features') = 'object'
                 AND describe ? 'compaction_control'
                 AND describe ? 'subordinate_visibility'))) IS TRUE);

-- 0030 forced RLS on lane_profile with a SELECT-only policy, so a non-superuser migration
-- principal (Supabase-like installs) cannot seed through it; lift FORCE around the seed
-- only. The table ends this migration forced again, exactly as 0030 left it.
ALTER TABLE mission_control.lane_profile NO FORCE ROW LEVEL SECURITY;

